"use client"

import {
  getPartText,
  type ContextEventForUI,
  type ContextReactionForUI,
  type ContextSessionForUI,
} from "@ekairos/events/react"
import { type CSSProperties, useMemo } from "react"

import {
  buildEventTimeline,
  reactionDurationMs,
  reactionTitle,
} from "./reaction-graph"
import "./event-timeline.css"

export type EventTimelineViewProps = {
  session: ContextSessionForUI
  selectedId: string | null
  onSelect(id: string): void
  variant?: "inspector" | "chat"
  omit?: ReadonlySet<string>
}

const TIMELINE_ROW_HEIGHT = 27
const TIMELINE_LANE_WIDTH = 12
const TIMELINE_RAIL_BASE = 15
const TIMELINE_BRANCH_COLORS = [
  "var(--event-timeline-branch-0, #5c6a70)",
  "var(--event-timeline-branch-1, #75aadb)",
  "var(--event-timeline-branch-2, #d4af37)",
  "var(--event-timeline-branch-3, #65d688)",
  "var(--event-timeline-branch-4, #cfc3f5)",
  "var(--event-timeline-branch-5, #ff5c67)",
] as const

export function EventTimelineView({
  session,
  selectedId,
  onSelect,
  variant = "inspector",
  omit,
}: EventTimelineViewProps) {
  const timeline = useMemo(() => buildEventTimeline(session), [session])
  const rows = useMemo(
    () => omit ? timeline.rows.filter(row => !omit.has(row.event.id)) : timeline.rows,
    [timeline, omit],
  )
  const selected = useMemo(
    () => allSessionReactions(session).find(reaction => reaction.id === selectedId) ?? null,
    [session, selectedId],
  )
  const causeIds = useMemo(() => new Set(selected?.causeIds ?? []), [selected])
  const reactionCount = new Set(rows.map(row => row.producer?.id).filter(Boolean)).size
  const firstProducerRow = useMemo(() => {
    const first = new Map<string, number>()
    rows.forEach((row, index) => {
      const id = row.producer?.id
      if (id && !first.has(id)) first.set(id, index)
    })
    return first
  }, [rows])
  const chat = variant === "chat"
  const positions = useMemo(() => new Map(
    rows.map((row, index) => [row.event.id, { index, lane: row.lane, branch: row.branch }]),
  ), [rows])
  const railWidth = TIMELINE_RAIL_BASE + timeline.lanes * TIMELINE_LANE_WIDTH + 4
  const orderedEdges = [
    ...timeline.edges.filter(edge => edge.reactionId !== selectedId),
    ...timeline.edges.filter(edge => edge.reactionId === selectedId),
  ]

  return (
    <section className={`event-timeline ${variant}`} data-variant={variant}>
      {chat ? null : (
        <header className="timeline-toolbar">
          <strong>{session.definition}</strong>
          <span>{rows.length} Events / {reactionCount} Reactions</span>
        </header>
      )}
      <div className="timeline" style={{ "--rail-w": `${railWidth}px` } as CSSProperties}>
        <svg
          aria-hidden="true"
          className="timeline-edges"
          height={rows.length * TIMELINE_ROW_HEIGHT}
          width={railWidth}
        >
          {orderedEdges.map(edge => {
            const from = positions.get(edge.from)
            const to = positions.get(edge.to)
            if (!from || !to) return null
            const active = edge.reactionId === selectedId
            return (
              <path
                className={[edge.kind, active ? "selected" : ""].filter(Boolean).join(" ")}
                d={timelineEdgePath(from, to, railWidth)}
                key={edge.id}
                stroke={active
                  ? "var(--event-timeline-accent, #7defff)"
                  : branchColor(Math.max(from.branch, to.branch))}
              />
            )
          })}
        </svg>
        {rows.map((row, index) => {
          const producer = row.producer
          const duration = producer ? reactionDurationMs(producer) : null
          const repeatedProducer =
            producer !== null && firstProducerRow.get(producer.id) !== index
          const summary = eventSummary(row.event)
          const classNames = [
            "timeline-row",
            producer && producer.id === selectedId ? "selected" : "",
            causeIds.has(row.event.id) ? "cause" : "",
            row.child ? "child" : "",
            `durability-${row.event.durability ?? "durable"}`,
            producer?.status === "failed" ? "failed" : "",
            producer?.status === "running" ? "running" : "",
          ].filter(Boolean).join(" ")

          return (
            <button
              aria-pressed={producer ? producer.id === selectedId : undefined}
              className={classNames}
              disabled={!producer}
              key={row.event.id}
              onClick={() => producer && onSelect(producer.id)}
              title={producer ? reactionTitle(producer) : row.event.id}
              type="button"
            >
              <span
                className="timeline-rail"
                style={{
                  "--dot-r": `${TIMELINE_RAIL_BASE + row.lane * TIMELINE_LANE_WIDTH}px`,
                  "--dot": branchColor(row.branch),
                } as CSSProperties}
              >
                <span className="timeline-dot" />
              </span>
              {chat ? (
                summary
                  ? <span className="timeline-summary">{summary}</span>
                  : <span className="timeline-type">{row.event.type}</span>
              ) : (
                <>
                  <span className="timeline-type">{row.event.type}</span>
                  <span className="timeline-summary">{summary}</span>
                </>
              )}
              {row.branchOf ? (
                <span className="timeline-badge" title={row.branchOf}>
                  {compactName(row.branchOf)}
                </span>
              ) : null}
              <span className="timeline-reaction">
                {producer
                  ? repeatedProducer
                    ? "·"
                    : `${producer.type.split(":")[0]}${duration === null ? "" : ` ${(duration / 1000).toFixed(1)}s`}`
                  : "trigger"}
              </span>
              {chat ? null : <time>{clock(row.event.createdAt)}</time>}
            </button>
          )
        })}
      </div>
    </section>
  )
}

function allSessionReactions(session: ContextSessionForUI): ContextReactionForUI[] {
  const rows = [
    ...session.reactions,
    ...session.children.flatMap(allSessionReactions),
  ]
  return [...new Map(rows.map(reaction => [reaction.id, reaction])).values()]
}

function compactName(value: string) {
  const base = value.split(":")[0] ?? value
  return base.split(".").pop() || base
}

function branchColor(branch: number) {
  return TIMELINE_BRANCH_COLORS[branch % TIMELINE_BRANCH_COLORS.length]!
}

function timelineEdgePath(
  from: { index: number; lane: number },
  to: { index: number; lane: number },
  railWidth: number,
) {
  const x1 = railWidth - TIMELINE_RAIL_BASE - from.lane * TIMELINE_LANE_WIDTH
  const x2 = railWidth - TIMELINE_RAIL_BASE - to.lane * TIMELINE_LANE_WIDTH
  const y1 = from.index * TIMELINE_ROW_HEIGHT + TIMELINE_ROW_HEIGHT / 2
  const y2 = to.index * TIMELINE_ROW_HEIGHT + TIMELINE_ROW_HEIGHT / 2
  if (x1 === x2) return `M ${x1} ${y1} L ${x2} ${y2}`
  const bend = Math.max(y1, y2 - TIMELINE_ROW_HEIGHT)
  return [
    `M ${x1} ${y1}`,
    `L ${x1} ${bend}`,
    `C ${x1} ${bend + TIMELINE_ROW_HEIGHT * 0.65}, ${x2} ${y2 - TIMELINE_ROW_HEIGHT * 0.65}, ${x2} ${y2}`,
  ].join(" ")
}

function eventSummary(event: ContextEventForUI) {
  const payload = event.payload as Record<string, unknown> | null
  const direct = typeof event.payload === "string"
    ? event.payload
    : typeof payload?.text === "string"
      ? payload.text
      : typeof payload?.summary === "string"
        ? payload.summary
        : event.eventParts.map(getPartText).filter(Boolean).join("\n")
  if (direct) return clip(direct)

  const action = event.eventParts.find(part => part.type === "action")
  if (action) {
    const content = action.content as Record<string, unknown> | null
    const name = typeof content?.actionName === "string" ? content.actionName : ""
    const status = typeof content?.status === "string" ? content.status : ""
    if (name) return clip(status ? `${name} · ${status}` : name)
  }

  if (payload) {
    if (typeof payload.command === "string") return clip(`$ ${payload.command}`)
    if (typeof payload.message === "string") return clip(payload.message)
    if (Array.isArray(payload.files) && payload.files.length > 0) {
      const names = payload.files
        .map(file => file && typeof file === "object"
          ? (file as Record<string, unknown>).name
            ?? (file as Record<string, unknown>).filename
            ?? (file as Record<string, unknown>).path
          : undefined)
        .filter((name): name is string => typeof name === "string" && name.length > 0)
      const label = names.slice(0, 3).join(", ")
      const count = `${payload.files.length} file${payload.files.length === 1 ? "" : "s"}`
      return clip(label ? `${count} · ${label}` : count)
    }
    for (const key of ["records", "rows", "items"] as const) {
      if (Array.isArray(payload[key])) return `${payload[key].length} ${key}`
    }
    for (const key of ["repository", "url", "path", "branch", "name", "datasetId", "error"] as const) {
      if (typeof payload[key] === "string" && payload[key]) return clip(payload[key])
    }
  }

  return ""
}

function clip(value: string, size = 62) {
  const text = value.replace(/\s+/g, " ").trim()
  return text.length > size ? `${text.slice(0, size - 3)}...` : text
}

function clock(value: string | Date | undefined) {
  if (!value) return "-"
  return new Intl.DateTimeFormat("en-GB", {
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hourCycle: "h23",
  }).format(new Date(value))
}

import type {
  ContextEventForUI,
  ContextReactionForUI,
  ContextSessionForUI,
} from "@ekairos/events/react"

// Canonical source for the Ekairos reaction-graph registry item.
export type TimelineRow = Readonly<{
  event: ContextEventForUI
  lane: number
  producer: ContextReactionForUI | null
  child: boolean
  branch: number
  branchOf: string | null
}>

export type TimelineEdge = Readonly<{
  id: string
  reactionId: string
  from: string
  to: string
  kind: "flow" | "spawn"
}>

export type EventTimeline = Readonly<{
  rows: readonly TimelineRow[]
  edges: readonly TimelineEdge[]
  lanes: number
}>

const MAX_LANES = 5

// Chronological Event log rendered as a git-style graph. Edges are the real
// cause->effect connections of each Reaction; every non-trigger Event is
// guaranteed an incoming edge (soft "spawn" ones for Events no Reaction
// produces), so every line traces back to the trigger. Lanes come from a
// fixed pool: a line keeps its lane until its last child, continuations
// inherit it, fan-out siblings take the nearest free lane, and convergences
// land on the central lane of their parents.
export function buildEventTimeline(session: ContextSessionForUI): EventTimeline {
  const rootId = session.rootReaction?.id
  const sessions = collectSessions(session)
  const allReactions = uniqueReactions(sessions.flatMap(row => row.reactions))
    .sort((left, right) => left.position - right.position)
  const reactions = allReactions.filter(reaction => reaction.id !== rootId)
  const events = new Map<string, ContextEventForUI>()
  for (const row of sessions) {
    if (row.trigger) events.set(row.trigger.id, row.trigger)
  }
  for (const reaction of reactions) {
    reaction.causes.forEach(event => events.set(event.id, event))
    reaction.effects.forEach(event => events.set(event.id, event))
    reaction.liveEffects.forEach(event => events.set(event.id, event))
  }

  const producers = new Map<string, ContextReactionForUI>()
  for (const reaction of reactions) {
    const effects = reaction.effects.length > 0 ? reaction.effects : reaction.liveEffects
    for (const effect of effects) {
      if (!producers.has(effect.id)) producers.set(effect.id, reaction)
    }
  }

  const branches = new Map<string, number>()
  const branchStarts = new Map<string, string>()
  const sessionByTrigger = new Map<string, ContextSessionForUI>()
  sessions.forEach((row, index) => {
    if (index === 0) return
    if (row.trigger) {
      branchStarts.set(row.trigger.id, row.definition)
      sessionByTrigger.set(row.trigger.id, row)
      if (!branches.has(row.trigger.id)) branches.set(row.trigger.id, index)
    }
    for (const reaction of row.reactions) {
      for (const effect of [...reaction.effects, ...reaction.liveEffects]) {
        if (!branches.has(effect.id)) branches.set(effect.id, index)
      }
    }
  })

  const ordered = [...events.values()].sort(eventOrder)
  const indexOf = new Map(ordered.map((event, index) => [event.id, index]))

  const edges: TimelineEdge[] = []
  for (const reaction of reactions) {
    const sources = reaction.causeIds.filter(id => indexOf.has(id))
    const effects = (reaction.effects.length > 0 ? reaction.effects : reaction.liveEffects)
      .map(event => event.id)
      .filter(id => indexOf.has(id))
    if (sources.length === 0 || effects.length === 0) continue
    const first = effects[0]!
    sources.forEach((source, index) => edges.push(Object.freeze({
      id: `${reaction.id}:cause:${index}`,
      reactionId: reaction.id,
      from: source,
      to: first,
      kind: "flow" as const,
    })))
    for (let index = 1; index < effects.length; index += 1) {
      edges.push(Object.freeze({
        id: `${reaction.id}:effect:${index}`,
        reactionId: reaction.id,
        from: effects[index - 1]!,
        to: effects[index]!,
        kind: "flow" as const,
      }))
    }
  }

  // Guarantee connectivity back to the trigger: any Event without an incoming
  // edge hangs off its spawning Reaction when resolvable, otherwise off the
  // newest preceding main-line Event.
  const hasIncoming = new Set(edges.map(edge => edge.to))
  ordered.forEach((event, index) => {
    if (index === 0 || hasIncoming.has(event.id)) return
    let anchor: ContextEventForUI | undefined
    let reactionId = ""
    const owner = sessionByTrigger.get(event.id)
    const parent = owner
      ? allReactions.find(reaction => reaction.id === owner.parentReactionId)
      : undefined
    if (parent) {
      const at = new Date(event.createdAt).valueOf()
      anchor = [...parent.causes, ...parent.effects, ...parent.liveEffects]
        .filter(candidate => indexOf.has(candidate.id) && candidate.id !== event.id)
        .filter(candidate => new Date(candidate.createdAt).valueOf() <= at)
        .sort(eventOrder)
        .at(-1)
      reactionId = parent.id
    }
    if (!anchor) {
      for (let back = index - 1; back >= 0; back -= 1) {
        const candidate = ordered[back]!
        if ((branches.get(candidate.id) ?? 0) === 0) { anchor = candidate; break }
      }
      anchor ??= ordered[index - 1]
    }
    if (!anchor) return
    edges.push(Object.freeze({
      id: `${event.id}:spawn`,
      reactionId: reactionId || producers.get(anchor.id)?.id || "",
      from: anchor.id,
      to: event.id,
      kind: "spawn" as const,
    }))
    hasIncoming.add(event.id)
  })

  const childrenOf = new Map<string, number[]>()
  const parentsOf = new Map<string, string[]>()
  for (const edge of edges) {
    childrenOf.set(edge.from, [...(childrenOf.get(edge.from) ?? []), indexOf.get(edge.to)!])
    if (!(parentsOf.get(edge.to) ?? []).includes(edge.from)) {
      parentsOf.set(edge.to, [...(parentsOf.get(edge.to) ?? []), edge.from])
    }
  }
  const lastChild = (id: string) =>
    Math.max(indexOf.get(id) ?? 0, ...(childrenOf.get(id) ?? []))

  const laneOf = new Map<string, number>()
  const busyUntil = Array<number>(MAX_LANES).fill(-1)
  const freeLane = (preferred: number, index: number) => {
    let best = -1
    let bestDistance = Infinity
    for (let lane = 0; lane < busyUntil.length; lane += 1) {
      if (busyUntil[lane]! >= index) continue
      const distance = Math.abs(lane - preferred)
      if (distance < bestDistance) { best = lane; bestDistance = distance }
    }
    return best >= 0 ? best : busyUntil.indexOf(Math.min(...busyUntil))
  }
  ordered.forEach((event, index) => {
    const parents = (parentsOf.get(event.id) ?? []).filter(id => laneOf.has(id))
    let lane: number
    if (parents.length === 0) {
      lane = freeLane(0, index)
    } else if (parents.length === 1) {
      const parentLane = laneOf.get(parents[0]!)!
      lane = lastChild(parents[0]!) === index ? parentLane : freeLane(parentLane, index)
    } else {
      const parentLanes = parents.map(id => laneOf.get(id)!).sort((left, right) => left - right)
      const center = parentLanes[Math.floor(parentLanes.length / 2)]!
      const centerParent = parents.find(id => laneOf.get(id) === center)!
      lane = lastChild(centerParent) === index ? center : freeLane(center, index)
    }
    laneOf.set(event.id, lane)
    busyUntil[lane] = Math.max(busyUntil[lane]!, lastChild(event.id))
  })

  return Object.freeze({
    rows: Object.freeze(ordered.map(event => Object.freeze({
      event,
      lane: laneOf.get(event.id) ?? 0,
      producer: producers.get(event.id) ?? null,
      child: branches.has(event.id),
      branch: branches.get(event.id) ?? 0,
      branchOf: branchStarts.get(event.id) ?? null,
    }))),
    edges: Object.freeze(edges),
    lanes: Math.max(1, ...[...laneOf.values()].map(lane => lane + 1)),
  })
}

export function reactionTitle(reaction: ContextReactionForUI) {
  if (reaction.type === "emit") {
    return `Publish ${shortType(reaction.effects[0]?.type ?? reaction.liveEffects[0]?.type ?? "Event")}`
  }
  if (reaction.type === "action") {
    const name = [...reaction.effects, ...reaction.liveEffects]
      .map(actionName)
      .find(Boolean)
    return name ? `Execute ${name}` : "Execute domain action"
  }
  if (reaction.type === "dataset") return "Materialize formal Dataset"
  if (reaction.type === "agent") return firstSentence(reaction.instruction) || "Run model inference"
  if (reaction.type === "child") return reaction.instruction || "Run child Reaction"
  return reaction.instruction || reaction.type
}

export function reactionDurationMs(reaction: ContextReactionForUI) {
  const start = new Date(reaction.createdAt).valueOf()
  const finish = reaction.updatedAt ? new Date(reaction.updatedAt).valueOf() : Date.now()
  return Number.isFinite(start) && Number.isFinite(finish) ? Math.max(0, finish - start) : null
}

function actionName(event: ContextEventForUI | null | undefined) {
  for (const part of event?.eventParts ?? []) {
    if (part.type !== "action") continue
    const content = part.content as Record<string, unknown>
    if (typeof content.actionName === "string") return content.actionName
  }
  return ""
}

function shortType(type: string) {
  const pieces = type.split(".")
  return pieces[pieces.length - 1] || type
}

function firstSentence(value: string | undefined) {
  const text = String(value ?? "").trim()
  if (!text) return ""
  const end = text.search(/[.!?](?:\s|$)/)
  return (end >= 0 ? text.slice(0, end) : text).trim()
}

function eventOrder(left: ContextEventForUI, right: ContextEventForUI) {
  const created = new Date(left.createdAt).valueOf() - new Date(right.createdAt).valueOf()
  return created || left.id.localeCompare(right.id)
}

function collectSessions(session: ContextSessionForUI): ContextSessionForUI[] {
  return [session, ...session.children.flatMap(collectSessions)]
}

function uniqueReactions(reactions: readonly ContextReactionForUI[]) {
  return [...new Map(reactions.map(reaction => [reaction.id, reaction])).values()]
}

.event-timeline {
  --event-timeline-surface: var(--panel-soft, #0a0d0f);
  --event-timeline-panel: var(--panel, #050607);
  --event-timeline-line: var(--line-soft, rgba(255, 255, 255, 0.07));
  --event-timeline-grid: rgba(255, 255, 255, 0.016);
  --event-timeline-text: var(--text, #f4f7f8);
  --event-timeline-muted: var(--muted, rgba(244, 247, 248, 0.68));
  --event-timeline-dim: var(--dim, rgba(244, 247, 248, 0.45));
  --event-timeline-accent: var(--cyan, #7defff);
  --event-timeline-accent-deep: var(--cyan-deep, #1c5964);
  --event-timeline-sky: var(--sky, #75aadb);
  --event-timeline-gold: var(--gold, #d4af37);
  --event-timeline-danger: var(--red, #ff5c67);
  --event-timeline-type: #8fd7e6;
  --event-timeline-hover: rgba(255, 255, 255, 0.025);
  --event-timeline-selected: rgba(125, 239, 255, 0.06);
  --event-timeline-cause: rgba(125, 239, 255, 0.03);
  --event-timeline-stream-glow: rgba(125, 239, 255, 0.4);
  --event-timeline-badge-line: rgba(117, 170, 219, 0.4);
  --event-timeline-font-mono: var(
    --font-mono,
    ui-monospace,
    SFMono-Regular,
    Menlo,
    Consolas,
    monospace
  );
  --event-timeline-ease: var(--ease, 140ms ease);

  height: 100%;
  min-width: 0;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  color: var(--event-timeline-text);
}

.event-timeline.chat {
  display: block;
  height: auto;
}

.event-timeline .timeline-toolbar {
  display: flex;
  align-items: baseline;
  gap: 8px;
  padding: 9px 14px;
  border-bottom: 1px solid var(--event-timeline-line);
  background: var(--event-timeline-panel);
}

.event-timeline .timeline-toolbar strong {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--event-timeline-muted);
  font: 600 9px/1 var(--event-timeline-font-mono);
  text-transform: uppercase;
  letter-spacing: 0.1em;
}

.event-timeline .timeline-toolbar span {
  margin-left: auto;
  flex: 0 0 auto;
  color: var(--event-timeline-dim);
  font: 8px/1 var(--event-timeline-font-mono);
}

.event-timeline .timeline {
  position: relative;
  margin: 0;
  padding: 6px 0 14px;
  min-height: 0;
  overflow: auto;
  background-color: var(--event-timeline-surface);
  background-image: linear-gradient(
    var(--event-timeline-grid) 1px,
    transparent 1px
  );
  background-size: 27px 27px;
}

.event-timeline.chat .timeline {
  overflow: visible;
  padding: 4px 0 8px;
  background: transparent;
}

.event-timeline .timeline-edges {
  position: absolute;
  top: 6px;
  right: 0;
  z-index: 2;
  pointer-events: none;
}

.event-timeline.chat .timeline-edges {
  top: 4px;
}

.event-timeline .timeline-edges path {
  fill: none;
  stroke-width: 1.5;
  opacity: 0.4;
}

.event-timeline .timeline-edges path.spawn {
  stroke-dasharray: 3 4;
  opacity: 0.28;
}

.event-timeline .timeline-edges path.selected {
  stroke-width: 2;
  opacity: 1;
  filter: drop-shadow(0 0 5px var(--event-timeline-stream-glow));
}

.event-timeline .timeline-row {
  position: relative;
  width: 100%;
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 0 calc(var(--rail-w, 30px) + 6px) 0 14px;
  height: 27px;
  overflow: hidden;
  border: 0;
  background: transparent;
  color: var(--event-timeline-text);
  text-align: left;
  cursor: pointer;
  transition: background var(--event-timeline-ease);
}

.event-timeline .timeline-row:disabled {
  cursor: default;
  opacity: 1;
}

.event-timeline .timeline-row > * {
  position: relative;
  z-index: 3;
  flex: 0 0 auto;
  white-space: nowrap;
}

.event-timeline .timeline-row:not(:disabled):hover {
  background: var(--event-timeline-hover);
}

.event-timeline .timeline-row.selected {
  background: var(--event-timeline-selected);
  box-shadow: inset 2px 0 0 var(--event-timeline-accent);
}

.event-timeline .timeline-row.cause {
  background: var(--event-timeline-cause);
}

.event-timeline .timeline-rail {
  position: absolute;
  z-index: 2;
  inset: 0 0 0 auto;
  width: 0;
}

.event-timeline .timeline-dot {
  position: absolute;
  top: 50%;
  right: var(--dot-r, 15px);
  transform: translate(50%, -50%);
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--event-timeline-surface);
  border: 1.25px solid var(--dot, var(--event-timeline-dim));
  opacity: 0.9;
}

.event-timeline .timeline-row.selected .timeline-dot,
.event-timeline .timeline-row.cause .timeline-dot,
.event-timeline .timeline-row.durability-streaming .timeline-dot,
.event-timeline .timeline-row.running .timeline-dot,
.event-timeline .timeline-row.failed .timeline-dot {
  opacity: 1;
}

.event-timeline .timeline-row.selected .timeline-dot {
  border-color: var(--event-timeline-accent);
  background: var(--event-timeline-accent-deep);
}

.event-timeline .timeline-row.cause .timeline-dot {
  border-color: var(--event-timeline-accent-deep);
}

.event-timeline .timeline-row.durability-streaming .timeline-dot {
  border-color: var(--event-timeline-accent);
  box-shadow: 0 0 6px var(--event-timeline-stream-glow);
}

.event-timeline .timeline-row.durability-optimistic .timeline-dot {
  border-color: var(--event-timeline-gold);
}

.event-timeline .timeline-row.failed .timeline-dot {
  border-color: var(--event-timeline-danger);
}

.event-timeline .timeline-row.running .timeline-dot {
  border-color: var(--event-timeline-accent);
  animation: event-timeline-pulse 1.2s ease-in-out infinite;
}

.event-timeline .timeline-type {
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 180px;
  color: var(--event-timeline-type);
  font: 600 9px/1 var(--event-timeline-font-mono);
}

.event-timeline.chat .timeline-type {
  flex: 1 1 auto;
  max-width: none;
}

.event-timeline .timeline-row.child .timeline-type {
  color: var(--event-timeline-sky);
}

.event-timeline .timeline-summary {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  color: var(--event-timeline-muted);
  font-size: 10px;
}

.event-timeline.chat .timeline-summary {
  color: var(--event-timeline-muted);
}

.event-timeline .timeline-badge {
  padding: 1px 6px;
  border: 1px solid var(--event-timeline-badge-line);
  border-radius: 8px;
  color: var(--event-timeline-sky);
  font: 500 7px/1.5 var(--event-timeline-font-mono);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.event-timeline .timeline-reaction {
  color: var(--event-timeline-dim);
  font: 8px/1 var(--event-timeline-font-mono);
}

.event-timeline .timeline-row.failed .timeline-reaction {
  color: var(--event-timeline-danger);
}

.event-timeline .timeline-row time {
  color: var(--event-timeline-dim);
  font: 8px/1 var(--event-timeline-font-mono);
}

@keyframes event-timeline-pulse {
  50% {
    opacity: 0.35;
  }
}

@media (prefers-reduced-motion: reduce) {
  .event-timeline .timeline-row.running .timeline-dot {
    animation: none;
  }
}
